#!/usr/bin/env python3
"""Fetch every order page and every referenced customer from the local order service.

Usage: fetch.py <data_dir>

Raw responses are stored under <data_dir>; every non-200 response (and every token
refresh) is appended in full to <data_dir>/events.log so the behaviour can be reviewed.
Nothing is computed here.
"""
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 200


class Client:
    def __init__(self, data_dir):
        self.data_dir = data_dir
        self.token = None
        self.tokens_fetched = 0
        self.requests_with_token = 0
        self.stats = {"429": 0, "401": 0, "5xx": 0, "net": 0, "other": 0}
        self.log_path = os.path.join(data_dir, "events.log")

    def log(self, msg):
        line = "%s %s" % (time.strftime("%H:%M:%S"), msg)
        with open(self.log_path, "a") as fh:
            fh.write(line + "\n")
        print(line, flush=True)

    def _raw(self, method, path):
        req = urllib.request.Request(
            BASE + path, method=method, data=b"" if method == "POST" else None
        )
        if method == "GET" and self.token:
            req.add_header("Authorization", "Bearer " + self.token)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as err:
            return err.code, dict(err.headers), err.read()
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as err:
            return None, {}, repr(err).encode()

    @staticmethod
    def _retry_after(headers, body):
        """Return the number of seconds the service asked us to wait, or None."""
        for key, val in headers.items():
            if key.lower() == "retry-after":
                try:
                    return float(val)
                except ValueError:
                    return None
        try:
            parsed = json.loads(body)
        except ValueError:
            return None
        if isinstance(parsed, dict):
            for key in ("retry_after", "retry_after_seconds", "retry_in", "wait"):
                if isinstance(parsed.get(key), (int, float)):
                    return float(parsed[key])
        return None

    def fetch_token(self):
        for attempt in range(1, MAX_ATTEMPTS + 1):
            status, headers, body = self._raw("POST", "/token")
            if status == 200:
                tok = json.loads(body)["token"]
                self.token = tok
                self.tokens_fetched += 1
                self.requests_with_token = 0
                self.log("TOKEN fetched #%d: %s" % (self.tokens_fetched, tok))
                return
            self.log("TOKEN request got %s headers=%s body=%r" % (status, headers, body[:300]))
            wait = self._retry_after(headers, body) if status == 429 else None
            time.sleep(wait if wait is not None else min(2 * attempt, 10))
        raise RuntimeError("could not obtain a token")

    def get_json(self, path, treat_404_as_missing=False):
        """GET an authenticated path and return parsed JSON (or None for a confirmed 404)."""
        not_found_seen = 0
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if self.token is None:
                self.fetch_token()
            status, headers, body = self._raw("GET", path)
            self.requests_with_token += 1
            if status == 200:
                try:
                    return json.loads(body)
                except ValueError:
                    self.stats["other"] += 1
                    self.log("GET %s 200 but body is not JSON: %r" % (path, body[:300]))
                    time.sleep(1)
                    continue
            self.log(
                "GET %s -> %s (request #%d on this token) headers=%s body=%r"
                % (path, status, self.requests_with_token, headers, body[:400])
            )
            if status in (401, 403):
                self.stats["401"] += 1
                self.token = None
                continue
            if status == 429:
                self.stats["429"] += 1
                wait = self._retry_after(headers, body)
                if wait is None:
                    self.log("  429 without a parsable wait time; waiting 5s")
                    wait = 5.0
                self.log("  rate limited: waiting %.2fs as instructed" % wait)
                time.sleep(wait)
                continue
            if status == 404 and treat_404_as_missing:
                not_found_seen += 1
                if not_found_seen >= 3:
                    return None  # confirmed three times
                time.sleep(0.5)
                continue
            if status is None:
                self.stats["net"] += 1
            elif status >= 500:
                self.stats["5xx"] += 1
            else:
                self.stats["other"] += 1
            time.sleep(min(attempt, 5))
        raise RuntimeError("giving up on %s after %d attempts" % (path, MAX_ATTEMPTS))


def main():
    data_dir = sys.argv[1]
    os.makedirs(data_dir, exist_ok=True)
    client = Client(data_dir)
    client.log("=== fetch run start ===")

    # ---- order pages: follow "next" until null -------------------------------------
    path = "/orders?page=1"
    pages = []
    while path:
        data = client.get_json(path)
        want = int(path.split("page=")[1])
        for key in ("page", "total_pages", "items", "next"):
            if key not in data:
                raise RuntimeError("page %s is missing key %r: %s" % (path, key, list(data)))
        if data["page"] != want:
            raise RuntimeError("asked for page %d, got page %r" % (want, data["page"]))
        with open(os.path.join(data_dir, "page_%03d.json" % want), "w") as fh:
            json.dump(data, fh)
        pages.append(want)
        client.log(
            "page %d/%s: %d items, next=%r"
            % (data["page"], data["total_pages"], len(data["items"]), data["next"])
        )
        path = data["next"]
    client.log("order pages fetched: %s" % pages)

    # ---- customers: every distinct customer_id seen on any order, fetched once ------
    customer_ids = set()
    for p in pages:
        with open(os.path.join(data_dir, "page_%03d.json" % p)) as fh:
            for order in json.load(fh)["items"]:
                customer_ids.add(order["customer_id"])
    cust_path = os.path.join(data_dir, "customers.json")
    customers = {}
    if os.path.exists(cust_path):
        with open(cust_path) as fh:
            customers = json.load(fh)
    todo = sorted(c for c in customer_ids if c not in customers)
    client.log("distinct customer ids: %d (already cached: %d)" % (len(customer_ids), len(customers)))
    for cid in todo:
        rec = client.get_json("/customers/%s" % cid, treat_404_as_missing=True)
        customers[cid] = rec  # None == confirmed unknown id
        with open(cust_path, "w") as fh:
            json.dump(customers, fh, sort_keys=True)
    client.log("customers cached: %d" % len(customers))
    client.log("stats: tokens=%d %s" % (client.tokens_fetched, client.stats))
    client.log("=== fetch run end ===")


if __name__ == "__main__":
    main()

